mapper.select:
SELECT session_key FROM onsite_session_state_v1
WHERE parent_session_key = #{parentSessionKey}
ORDER BY created_at DESC LIMIT 1

mapper.update:
UPDATE onsite_session_state_v1
SET current_round = #{currentRound}, answered_signals_json = CAST(#{answeredSignalsJson} AS JSON)
WHERE session_key = #{sessionKey}
